diff --git a/internal/xds/credentials/access_token.go b/internal/xds/credentials/access_token.go
--- a/internal/xds/credentials/access_token.go
+++ b/internal/xds/credentials/access_token.go
@@ -0,0 +1,71 @@
+/*
+ *
+ * Copyright 2026 gRPC authors.
+ *
+ * Licensed under the Apache License, Version 2.0 (the "License");
+ * you may not use this file except in compliance with the License.
+ * You may obtain a copy of the License at
+ *
+ *     http://www.apache.org/licenses/LICENSE-2.0
+ *
+ * Unless required by applicable law or agreed to in writing, software
+ * distributed under the License is distributed on an "AS IS" BASIS,
+ * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+ * See the License for the specific language governing permissions and
+ * limitations under the License.
+ *
+ */
+
+package credentials
+
+import (
+	"context"
+	"fmt"
+
+	"google.golang.org/grpc/credentials"
+	"google.golang.org/protobuf/proto"
+	"google.golang.org/protobuf/types/known/anypb"
+
+	accesstokenpb "github.com/envoyproxy/go-control-plane/envoy/extensions/grpc_service/call_credentials/access_token/v3"
+)
+
+const accessTokenCredsTypeURL = "type.googleapis.com/envoy.extensions.grpc_service.call_credentials.access_token.v3.AccessTokenCredentials"
+
+func init() {
+	RegisterCallCredsBuilder(accessTokenCredsTypeURL, func(config *anypb.Any) (credentials.PerRPCCredentials, func(), error) {
+		var accessToken accesstokenpb.AccessTokenCredentials
+		if err := anypb.UnmarshalTo(config, &accessToken, proto.UnmarshalOptions{}); err != nil {
+			return nil, nil, fmt.Errorf("credentials: failed to unmarshal AccessTokenCredentials: %v", err)
+		}
+		if accessToken.GetToken() == "" {
+			return nil, nil, fmt.Errorf("credentials: access token must be non-empty")
+		}
+		// These credentials hold no resources; the no-op cleanup satisfies
+		// the registry contract.
+		return &accessTokenCallCreds{token: accessToken.GetToken()}, func() {}, nil
+	})
+}
+
+// accessTokenCallCreds implements credentials.PerRPCCredentials by attaching
+// a static bearer token to each RPC (gRFC A102). The credentials require
+// transport security: the token is only ever sent on connections that provide
+// privacy and integrity, and RPCs on weaker connections fail.
+type accessTokenCallCreds struct {
+	token string
+}
+
+// GetRequestMetadata returns the token as an authorization header. It fails
+// if the connection does not provide privacy and integrity.
+func (c *accessTokenCallCreds) GetRequestMetadata(ctx context.Context, _ ...string) (map[string]string, error) {
+	ri, _ := credentials.RequestInfoFromContext(ctx)
+	if err := credentials.CheckSecurityLevel(ri.AuthInfo, credentials.PrivacyAndIntegrity); err != nil {
+		return nil, fmt.Errorf("credentials: unable to transfer access token PerRPCCredentials: %v", err)
+	}
+	return map[string]string{"authorization": "Bearer " + c.token}, nil
+}
+
+// RequireTransportSecurity indicates whether the credentials require
+// transport security.
+func (c *accessTokenCallCreds) RequireTransportSecurity() bool {
+	return true
+}

diff --git a/internal/xds/credentials/access_token_test.go b/internal/xds/credentials/access_token_test.go
--- a/internal/xds/credentials/access_token_test.go
+++ b/internal/xds/credentials/access_token_test.go
@@ -0,0 +1,126 @@
+/*
+ *
+ * Copyright 2026 gRPC authors.
+ *
+ * Licensed under the Apache License, Version 2.0 (the "License");
+ * you may not use this file except in compliance with the License.
+ * You may obtain a copy of the License at
+ *
+ *     http://www.apache.org/licenses/LICENSE-2.0
+ *
+ * Unless required by applicable law or agreed to in writing, software
+ * distributed under the License is distributed on an "AS IS" BASIS,
+ * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+ * See the License for the specific language governing permissions and
+ * limitations under the License.
+ *
+ */
+
+package credentials_test
+
+import (
+	"context"
+	"strings"
+	"testing"
+
+	"google.golang.org/grpc/credentials"
+	xdscreds "google.golang.org/grpc/internal/xds/credentials"
+	"google.golang.org/protobuf/types/known/anypb"
+
+	accesstokenpb "github.com/envoyproxy/go-control-plane/envoy/extensions/grpc_service/call_credentials/access_token/v3"
+)
+
+const accessTokenCredsTypeURL = "type.googleapis.com/envoy.extensions.grpc_service.call_credentials.access_token.v3.AccessTokenCredentials"
+
+func accessTokenConfig(t *testing.T, token string) *anypb.Any {
+	t.Helper()
+	a, err := anypb.New(&accesstokenpb.AccessTokenCredentials{Token: token})
+	if err != nil {
+		t.Fatalf("Failed to marshal AccessTokenCredentials: %v", err)
+	}
+	return a
+}
+
+// Tests that building access token call credentials fails on malformed
+// configs and on an empty token.
+func (s) TestAccessTokenCredsBuild_Errors(t *testing.T) {
+	tests := []struct {
+		name    string
+		config  *anypb.Any
+		wantErr string
+	}{
+		{
+			name:    "unmarshal_failure",
+			config:  &anypb.Any{TypeUrl: accessTokenCredsTypeURL, Value: []byte{0xff}},
+			wantErr: "failed to unmarshal AccessTokenCredentials",
+		},
+		{
+			name:    "empty_token",
+			config:  accessTokenConfig(t, ""),
+			wantErr: "access token must be non-empty",
+		},
+	}
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			callCreds, _, err := xdscreds.GetCallCredsBuilder(accessTokenCredsTypeURL)(tt.config)
+			if err == nil || !strings.Contains(err.Error(), tt.wantErr) {
+				t.Fatalf("Build returned error %v, want error containing %q", err, tt.wantErr)
+			}
+			if callCreds != nil {
+				t.Errorf("Build returned non-nil call credentials alongside error")
+			}
+		})
+	}
+}
+
+// Tests that the token is attached as a bearer authorization header on
+// connections providing privacy and integrity, and that an error is returned
+// on weaker connections.
+func (s) TestAccessTokenCredsGetRequestMetadata(t *testing.T) {
+	callCreds, cleanup, err := xdscreds.GetCallCredsBuilder(accessTokenCredsTypeURL)(accessTokenConfig(t, "test-token"))
+	if err != nil {
+		t.Fatalf("Build failed: %v", err)
+	}
+	defer cleanup()
+
+	if !callCreds.RequireTransportSecurity() {
+		t.Error("RequireTransportSecurity() = false, want true")
+	}
+
+	ctx, cancel := context.WithTimeout(context.Background(), defaultTestTimeout)
+	defer cancel()
+
+	// The token must be attached on a connection with privacy and integrity.
+	secureCtx := credentials.NewContextWithRequestInfo(ctx, credentials.RequestInfo{
+		AuthInfo: &testAuthInfo{secLevel: credentials.PrivacyAndIntegrity},
+	})
+	md, err := callCreds.GetRequestMetadata(secureCtx)
+	if err != nil {
+		t.Fatalf("GetRequestMetadata() on a secure connection failed: %v", err)
+	}
+	if got, want := md["authorization"], "Bearer test-token"; got != want {
+		t.Fatalf("GetRequestMetadata() on a secure connection returned authorization header %q, want %q", got, want)
+	}
+
+	// RPCs on a connection that does not provide privacy and integrity must
+	// fail.
+	insecureCtx := credentials.NewContextWithRequestInfo(ctx, credentials.RequestInfo{
+		AuthInfo: &testAuthInfo{secLevel: credentials.NoSecurity},
+	})
+	if _, err := callCreds.GetRequestMetadata(insecureCtx); err == nil {
+		t.Fatal("GetRequestMetadata() on an insecure connection succeeded, want error")
+	}
+}
+
+// testAuthInfo implements credentials.AuthInfo for testing.
+type testAuthInfo struct {
+	secLevel credentials.SecurityLevel
+}
+
+func (t *testAuthInfo) AuthType() string {
+	return "test"
+}
+
+func (t *testAuthInfo) GetCommonAuthInfo() credentials.CommonAuthInfo {
+	return credentials.CommonAuthInfo{SecurityLevel: t.secLevel}
+}

diff --git a/internal/xds/credentials/credentials.go b/internal/xds/credentials/credentials.go
--- a/internal/xds/credentials/credentials.go
+++ b/internal/xds/credentials/credentials.go
@@ -0,0 +1,217 @@
+/*
+ *
+ * Copyright 2026 gRPC authors.
+ *
+ * Licensed under the Apache License, Version 2.0 (the "License");
+ * you may not use this file except in compliance with the License.
+ * You may obtain a copy of the License at
+ *
+ *     http://www.apache.org/licenses/LICENSE-2.0
+ *
+ * Unless required by applicable law or agreed to in writing, software
+ * distributed under the License is distributed on an "AS IS" BASIS,
+ * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+ * See the License for the specific language governing permissions and
+ * limitations under the License.
+ *
+ */
+
+// Package credentials provides the credentials used for xDS-configured side
+// channels (gRFC A102): built channel and call credentials paired with the
+// identity of the configuration they were built from, and registries of
+// credential builders keyed by proto type URL.
+package credentials
+
+import (
+	"bytes"
+	"fmt"
+	"sync"
+
+	"google.golang.org/grpc/credentials"
+	"google.golang.org/grpc/credentials/google"
+	"google.golang.org/grpc/credentials/insecure"
+	"google.golang.org/grpc/credentials/tls/certprovider"
+	"google.golang.org/protobuf/proto"
+	"google.golang.org/protobuf/types/known/anypb"
+
+	xdscredspb "github.com/envoyproxy/go-control-plane/envoy/extensions/grpc_service/channel_credentials/xds/v3"
+)
+
+const (
+	insecureCredsTypeURL      = "type.googleapis.com/envoy.extensions.grpc_service.channel_credentials.insecure.v3.InsecureCredentials"
+	googleDefaultCredsTypeURL = "type.googleapis.com/envoy.extensions.grpc_service.channel_credentials.google_default.v3.GoogleDefaultCredentials"
+	xdsCredsTypeURL           = "type.googleapis.com/envoy.extensions.grpc_service.channel_credentials.xds.v3.XdsCredentials"
+)
+
+func init() {
+	RegisterChannelCredsBuilder(insecureCredsTypeURL, func(*anypb.Any, CertProviderConfigResolver) (credentials.Bundle, func(), error) {
+		return insecure.NewBundle(), func() {}, nil
+	})
+	RegisterChannelCredsBuilder(googleDefaultCredsTypeURL, func(*anypb.Any, CertProviderConfigResolver) (credentials.Bundle, func(), error) {
+		return google.NewDefaultCredentials(), func() {}, nil
+	})
+	// The xds credential resolves to its required fallback credential, whose
+	// builder is looked up in the registry: a side-channel target is not an
+	// xDS cluster, so there is no xDS security configuration for it.
+	RegisterChannelCredsBuilder(xdsCredsTypeURL, func(config *anypb.Any, resolver CertProviderConfigResolver) (credentials.Bundle, func(), error) {
+		var xdsCfg xdscredspb.XdsCredentials
+		if err := anypb.UnmarshalTo(config, &xdsCfg, proto.UnmarshalOptions{}); err != nil {
+			return nil, nil, fmt.Errorf("credentials: failed to unmarshal XdsCredentials: %v", err)
+		}
+		fallback := xdsCfg.GetFallbackCredentials()
+		if fallback == nil {
+			return nil, nil, fmt.Errorf("credentials: xds credentials missing required fallback credentials")
+		}
+		if b := GetChannelCredsBuilder(fallback.GetTypeUrl()); b != nil {
+			return b(fallback, resolver)
+		}
+		return nil, nil, fmt.Errorf("credentials: unsupported fallback credentials type %q in xds credentials", fallback.GetTypeUrl())
+	})
+}
+
+// CertProviderConfigResolver resolves certificate provider instance names to
+// their configuration. It is implemented by the bootstrap config, and
+// declared here so that credential builders do not depend on the bootstrap
+// package.
+type CertProviderConfigResolver interface {
+	CertProviderConfigs() map[string]*certprovider.BuildableConfig
+}
+
+// ChannelCredsBuilder builds a channel credentials bundle from a GrpcService
+// channel credentials plugin config. The resolver gives access to the
+// certificate provider instances configured in the bootstrap config; builders
+// that do not reference them ignore it. The returned function releases the
+// resources held by the bundle when it is no longer needed.
+type ChannelCredsBuilder func(config *anypb.Any, resolver CertProviderConfigResolver) (credentials.Bundle, func(), error)
+
+// CallCredsBuilder builds per-RPC credentials from a GrpcService call
+// credentials plugin config. The returned function releases the resources
+// held by the credentials when they are no longer needed.
+type CallCredsBuilder func(config *anypb.Any) (credentials.PerRPCCredentials, func(), error)
+
+var (
+	// channelCredsBuilders is a map from proto type URL to
+	// ChannelCredsBuilder.
+	channelCredsBuilders = make(map[string]ChannelCredsBuilder)
+	// callCredsBuilders is a map from proto type URL to CallCredsBuilder.
+	callCredsBuilders = make(map[string]CallCredsBuilder)
+)
+
+// RegisterChannelCredsBuilder registers the builder for the given proto type
+// URL. Must be called at init time. Not thread safe.
+func RegisterChannelCredsBuilder(typeURL string, b ChannelCredsBuilder) {
+	channelCredsBuilders[typeURL] = b
+}
+
+// GetChannelCredsBuilder returns the builder registered for the given proto
+// type URL, or nil if there is none.
+func GetChannelCredsBuilder(typeURL string) ChannelCredsBuilder {
+	return channelCredsBuilders[typeURL]
+}
+
+// RegisterCallCredsBuilder registers the builder for the given proto type
+// URL. Must be called at init time. Not thread safe.
+func RegisterCallCredsBuilder(typeURL string, b CallCredsBuilder) {
+	callCredsBuilders[typeURL] = b
+}
+
+// GetCallCredsBuilder returns the builder registered for the given proto type
+// URL, or nil if there is none.
+func GetCallCredsBuilder(typeURL string) CallCredsBuilder {
+	return callCredsBuilders[typeURL]
+}
+
+// Identity identifies the configuration a credential was built from.
+type Identity struct {
+	// Type is the bootstrap credential type name for JSON-sourced
+	// credentials, or the proto type URL for proto-sourced ones. The two
+	// namespaces cannot collide: proto type URLs contain dots and slashes.
+	Type string
+	// Data is the raw JSON configuration, or the proto config value bytes.
+	Data []byte
+}
+
+// Equal reports whether i and other describe the same configuration.
+func (i Identity) Equal(other Identity) bool {
+	return i.Type == other.Type && bytes.Equal(i.Data, other.Data)
+}
+
+// ChannelCreds pairs a built credentials bundle with the identity of the
+// configuration it was built from.
+type ChannelCreds struct {
+	bundle   credentials.Bundle
+	identity Identity
+	cleanup  func()
+}
+
+// NewChannelCreds pairs the given bundle with its identity. cleanup releases
+// the resources held by the bundle and is run by Close; it must...

