diff --git a/internal/xds/httpfilter/rbac/rbac_test.go b/internal/xds/httpfilter/rbac/rbac_test.go
--- a/internal/xds/httpfilter/rbac/rbac_test.go
+++ b/internal/xds/httpfilter/rbac/rbac_test.go
@@ -0,0 +1,185 @@
+/*
+ *
